    "Java/OpenJDK/Opt": "java   -Dfile.encoding=UTF-8   -XX:+UseParallelGC   -XX:+UseLargePages   -XX:+AlwaysPreTouch   -XX:+UseCompressedOops   -XX:+OptimizeStringConcat   -XX:+UseStringDeduplication   -XX:+DisableExplicitGC   -XX:+UseCountedLoopSafepoints   -Xmx8g   -jar ./target/java-benchmarks-1.0-SNAPSHOT.jar",
    "Java/GraalVM/JIT": "java   -Dfile.encoding=UTF-8   -XX:+UseG1GC   -XX:+EnableJVMCI   -XX:+UseJVMCICompiler   -Djvmci.Compiler=graal   -XX:-TieredCompilation   -Xmx8g   -jar ./target/java-benchmarks-1.0-SNAPSHOT.jar",
    "Kotlin/JVM/Default": "java -Xmx8g -jar /src/kotlin/build/libs/benchmarks.jar",
    "Kotlin/JVM/Opt": "java   -server   -XX:+UseG1GC   -Xms2g   -Xmx2g   -XX:+AlwaysPreTouch   -XX:+OptimizeStringConcat   -XX:+UseCompressedOops   -Xmx8g   -jar /src/kotlin/build/libs/benchmarks.jar",
    "Kotlin/JVM/Max": "java   -server   -XX:+UseParallelGC   -Xms4g   -Xmx8g   -XX:+AlwaysPreTouch   -XX:+UseLargePages   -XX:+DisableExplicitGC   -Djava.security.egd=file:/dev/./urandom   -jar /src/kotlin/build/libs/benchmarks.jar",
    "Kotlin/GraalVM/JIT": "java   -XX:+UseG1GC   -XX:+EnableJVMCI   -XX:+UseJVMCICompiler   -Djvmci.Compiler=graal   -XX:-TieredCompilation   -Xmx8g   -jar /src/kotlin/build/libs/benchmarks.jar",
    "Scala/JVM/Default": "java -Xmx8g -jar /src/scala/target/benchmark.jar",
    "Scala/JVM/Opt": "java   -server   -XX:+UseG1GC   -Xms2g   -Xmx2g   -XX:+AlwaysPreTouch   -XX:+OptimizeStringConcat   -XX:+UseCompressedOops   -Xmx8g   -jar /src/scala/target/benchmark.jar",
    "Scala/JVM/Max": "java   -server   -XX:+UseParallelGC   -Xms4g   -Xmx8g   -XX:+AlwaysPreTouch   -XX:+UseLargePages   -XX:+DisableExplicitGC   -Djava.security.egd=file:/dev/./urandom   -jar /src/scala/target/benchmark.jar",
    "Scala/GraalVM/JIT": "java   -XX:+UseG1GC   -XX:+EnableJVMCI   -XX:+UseJVMCICompiler   -Djvmci.Compiler=graal   -XX:-TieredCompilation   -Xmx8g   -jar /src/scala/target/benchmark.jar",
    "Dart/AOT": "./target/dart_benchmark",
    "TypeScript/Node/Default": "node --max-old-space-size=4096 /src/typescript/target/dist/index.js",
    "TypeScript/Node/Opt": "node   --max-old-space-size=4096   --max-semi-space-size=256   --optimize-for-size   /src/typescript/target/dist/index.js",
    "TypeScript/Bun/JIT": "bun run /src/typescript/src/index.ts",
    "TypeScript/Bun/Compiled": "bun run /src/typescript/target/dist-bun/index.js",
    "TypeScript/Deno/Default": "deno run   --allow-all   --v8-flags=--max-old-space-size=4096   /src/typescript/src/index.ts",
    "TypeScript/Deno/Turbo": "deno run   --allow-all   --v8-flags=\"--max-old-space-size=4096,--concurrent-recompilation\"   --no-check   /src/typescript/src/index.ts",
    "Python/PYPY": "pypy3 main.py"
